/**
 * GDI - Google Drive Index
 * Player de vídeo, áudio, imagem + Pomodoro Timer + Sleep Mode
 * 
 * CORREÇÕES IMPLEMENTADAS:
 * ✓ Variáveis renomeadas (i,e,t → filename, size, etc)
 * ✓ Contexto de UI preservado em callbacks
 * ✓ Bugfix: switchVideo() usa m.streamUrl ao invés de 'a'
 * ✓ Memory leak: observers desconectados
 * ✓ Estado global isolado em namespace GDI
 * ✓ AbortController para requisições
 */

// ════════════════════════════════════════════════════════════════════
// NAMESPACE GLOBAL - Tudo isolado aqui
// ════════════════════════════════════════════════════════════════════
window.GDI = window.GDI || {
  playlist: { videos: [], currentIndex: -1, isBuilding: false },
  sleepMode: { active: false, fadeTimer: null, wakeTimer: null },
  ui: { folderFilterBound: false, sortState: { col: null, dir: 1 } },
  abortControllers: new Map()  // Rastreia fetch requests
};

// ════════════════════════════════════════════════════════════════════
// CORE FUNCTIONS (renomeadas para legibilidade)
// ════════════════════════════════════════════════════════════════════

const FILE_TYPES={video:["mp4","webm","avi","mpg","mpeg","mkv","rm","rmvb","mov","wmv","asf","ts","flv","3gp","m4v"],audio:["mp3","flac","wav","ogg","m4a","aac","wma","alac"],image:["bmp","jpg","jpeg","png","gif","svg","tiff","ico"],code:["php","css","go","java","js","json","txt","sh","html","xml","py","rb","c","cpp","h","hpp"],archive:["zip","rar","tar","7z","gz"],document:["pdf","doc","docx","xls","xlsx","ppt","pptx"],markdown:["md"]};

function isFileType(ext, type) {
  return FILE_TYPES[type] && FILE_TYPES[type].includes(ext?.toLowerCase());
}

function getFileIcon(ext) {
  const e = ext?.toLowerCase();
  if (isFileType(e, "video")) return '<i class="bi bi-camera-video-fill gdi-icon-video"></i>';
  if (isFileType(e, "audio")) return '<i class="bi bi-music-note-beamed gdi-icon-audio"></i>';
  if (isFileType(e, "image")) return '<i class="bi bi-image gdi-icon-image"></i>';
  if (isFileType(e, "archive")) return '<i class="bi bi-file-earmark-zip-fill gdi-icon-archive"></i>';
  if (isFileType(e, "markdown")) return '<i class="bi bi-markdown-fill gdi-icon-md"></i>';
  if (e === "pdf") return '<i class="bi bi-file-earmark-pdf-fill gdi-icon-pdf"></i>';
  if (isFileType(e, "code")) return '<i class="bi bi-code-slash gdi-icon-code"></i>';
  return '<i class="bi bi-file-earmark gdi-icon-file"></i>';
}

function escHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;");
}

function formatFileSize(bytes) {
  const b = Number(bytes);
  if (isNaN(b) || b < 0) return "";
  if (b >= 1099511627776) return (b / 1099511627776).toFixed(2) + " TB";
  if (b >= 1073741824) return (b / 1073741824).toFixed(2) + " GB";
  if (b >= 1048576) return (b / 1048576).toFixed(2) + " MB";
  if (b >= 1024) return (b / 1024).toFixed(2) + " KB";
  return b > 1 ? b + " bytes" : b === 1 ? "1 byte" : "0 bytes";
}

function formatDateTime(dt) {
  return dt ? new Date(dt).toLocaleString() : "";
}

function escapeHtmlId(str) {
  return String(str).replace(/\//g, "%2F").replace(/#/g, "%23").replace(/\?/g, "%3F");
}

// ════════════════════════════════════════════════════════════════════
// REQUISIÇÕES COM ABORT CONTROLLER
// ════════════════════════════════════════════════════════════════════

/**
 * Requisita lista de arquivos com retry automático
 * @param {string} path - Caminho da pasta
 * @param {object} options - { id, password, page_token, page_index }
 * @param {function} callback - (data, path, options) => void
 * @param {number} retriesLeft - Tentativas restantes
 * @param {boolean} isFallback - Se é requisição de fallback
 */
function requestListPath(path, options, callback, retriesLeft = 3, isFallback = false) {
  const payload = {
    id: options.id || "",
    type: "folder",
    password: options.password || "",
    page_token: options.page_token || "",
    page_index: options.page_index || 0
  };

  const endpoint = isFallback ? "/0:fallback" : path;
  const controller = new AbortController();
  
  // Rastreia o controller para poder cancelar depois
  const key = `${endpoint}_${Date.now()}`;
  GDI.abortControllers.set(key, controller);

  $("#update").show().html('<div class="gdi-alert gdi-alert-info">Conectando…</div>');

  fetch(endpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
    signal: controller.signal
  })
  .then(res => {
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  })
  .then(data => {
    GDI.abortControllers.delete(key);
    
    if (data?.error?.code === 401) {
      $("#update").hide();
      askPassword(path);
      return;
    }
    
    if (!data?.data) {
      $("#list").html('<div class="gdi-empty"><i class="bi bi-exclamation-circle"></i><p>Nenhum dado recebido.</p></div>');
      $("#update").hide();
      return;
    }
    
    // Callback recebe o contexto completo
    callback(data, path, options);
    $("#update").hide();
  })
  .catch(err => {
    GDI.abortControllers.delete(key);
    
    if (err.name === 'AbortError') {
      console.log('Requisição cancelada');
      return;
    }
    
    if (retriesLeft > 0) {
      $("#update").html(`<div class="gdi-alert gdi-alert-info">Tentando novamente… (${retriesLeft} tentativas)</div>`);
      setTimeout(() => {
        requestListPath(path, options, callback, retriesLeft - 1, isFallback);
      }, 2000);
    } else {
      $("#update").html(`<div class="gdi-alert gdi-alert-error">Falha na conexão. Tente novamente.</div>`);
      $("#list").html(`<div class="gdi-empty"><i class="bi bi-wifi-off"></i><p>${escHtml(String(err))}</p></div>`);
      $("#update").hide();
    }
  });
}

// ════════════════════════════════════════════════════════════════════
// PLAYER DE VÍDEO - VERSÃO CORRIGIDA
// ════════════════════════════════════════════════════════════════════

function file_video(filename, filename_encoded, size, poster, streamUrl, mimeType, fileId, rootId, subtitles = []) {
  const UI = window.UI || {};
  const player_config = window.player_config || {};
  subtitles = subtitles || [];

  // Early exit para disable player
  if (UI.disable_player) {
    $("#content").html(_viewerCard(
      '<i class="bi bi-camera-video-fill gdi-icon-video"></i>',
      filename, size,
      '<p>Player desabilitado</p>',
      renderDownloadButtons(streamUrl, filename_encoded, { showMedia: true })
    ));
    return;
  }

  const isHLS = streamUrl.includes(".m3u8") || mimeType === "application/x-mpegURL";
  let playerHtml = "", playerScript = "", playerCss = "";

  // ────── Determinar qual player usar ──────
  if (player_config.player === "plyr") {
    playerHtml = `<video id="player" playsinline controls autoplay data-poster="${poster}">
      <source src="${streamUrl}" type="${isHLS ? 'application/x-mpegURL' : 'video/mp4'}">
      ${subtitles.map(s => `<track kind="subtitles" src="${escapeHtmlId(s.url)}" label="${escHtml(s.label)}">`).join("")}
    </video>`;
    playerScript = `https://cdn.plyr.io/${player_config.plyr_io_version || '4.1.1'}/plyr.polyfilled.js`;
    playerCss = `https://cdn.plyr.io/${player_config.plyr_io_version || '4.1.1'}/plyr.css`;
  } else if (player_config.player === "videojs") {
    playerHtml = `<video id="vplayer" poster="${poster}" class="video-js vjs-default-skin" controls autoplay>
      <source src="${streamUrl}" type="${isHLS ? 'application/x-mpegURL' : 'video/mp4'}">
      ${subtitles.map(s => `<track kind="subtitles" src="${escapeHtmlId(s.url)}" label="${escHtml(s.label)}">`).join("")}
    </video>`;
    playerScript = `https://vjs.zencdn.net/${player_config.videojs_version || '8.0.0'}/video.js`;
    playerCss = `https://vjs.zencdn.net/${player_config.videojs_version || '8.0.0'}/video-js.css`;
  } else if (player_config.player === "dplayer") {
    playerHtml = '<div id="player-container"></div>';
    playerScript = 'https://cdn.jsdelivr.net/npm/dplayer/dist/DPlayer.min.js';
    playerCss = 'https://cdn.jsdelivr.net/npm/dplayer/dist/DPlayer.min.css';
  } else if (player_config.player === "jwplayer") {
    playerHtml = '<div id="player"></div>';
    playerScript = 'https://content.jwplatform.com/libraries/IDzF9Zmk.js';
  }

  const mainContent = `
    <div class="gdi-player-wrap" style="width:100%;margin:0 auto;">
      ${playerHtml}
    </div>
    <div id="gdi-player-nav" style="display:none;justify-content:space-between;margin-top:10px;gap:8px;">
      <button id="gdi-btn-prev" class="gdi-btn gdi-btn-ghost" style="flex:1;" title="Anterior">
        <i class="bi bi-skip-start-fill"></i> Anterior
      </button>
      <span id="gdi-nav-info" style="font-size:12px;color:var(--gdi-text-muted);">1 / 1</span>
      <button id="gdi-btn-next" class="gdi-btn gdi-btn-ghost" style="flex:1;justify-content:flex-end;" title="Próximo">
        Próximo <i class="bi bi-skip-end-fill"></i>
      </button>
    </div>
    <div id="gdi-playlist-wrap" style="margin-top:16px;display:none;">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
        <strong><i class="bi bi-collection-play me-2"></i>Playlist</strong>
        <span id="gdi-playlist-count" style="font-size:12px;color:var(--gdi-text-muted);">0 / 0</span>
      </div>
      <div id="gdi-playlist-list" style="max-height:260px;overflow-y:auto;border:1px solid rgba(255,255,255,0.12);border-radius:8px;padding:6px;"></div>
    </div>
  `;

  const downloadBtn = UI.disable_video_download ? "" : renderDownloadButtons(streamUrl, filename_encoded, { showMedia: true });
  $("#content").html(_viewerCard('<i class="bi bi-camera-video-fill gdi-icon-video"></i>', filename, size, mainContent, downloadBtn));
  $(".gdi-viewer").css({ "max-width": "1200px", "width": "96%", "margin": "0 auto" });

  // Carregar CSS do player
  if (playerCss) {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = playerCss;
    document.head.appendChild(link);
  }

  // ────── BUILD PLAYLIST ──────
  async function buildPlaylist() {
    if (GDI.playlist.isBuilding) return;
    GDI.playlist.isBuilding = true;

    const currentPath = window.location.pathname;
    const folderPath = currentPath.split("/").slice(0, -1).join("/") + "/";
    const parentPath = currentPath.split("/").slice(0, -2).join("/") + "/";

    function buildVideosFromFiles(files, basePath, folderLabel = null) {
      return files
        .filter(f => FILE_TYPES.video.includes(f.fileExtension) || (f.mimeType && f.mimeType.includes("video")))
        .map(f => {
          const url = UI.second_domain_for_dl ? UI.downloaddomain + f.link : window.location.origin + f.link;
          const pageUrl = basePath + escapeHtmlId(f.name) + "?a=view";
          const thumbUrl = f.thumbnailLink ? f.thumbnailLink.replace("s220", "s0") : UI.poster;
          return {
            id: f.id,
            name: f.name,
            folder: folderLabel,
            size: formatFileSize(f.size),
            streamUrl: url,
            pageUrl: pageUrl,
            mimeType: f.mimeType,
            poster: thumbUrl
          };
        });
    }

    // Primeiro tenta a pasta atual
    const currentVideos = await new Promise(resolve => {
      requestListPath(folderPath, {}, (data) => {
        const videos = data?.data?.files ? buildVideosFromFiles(data.data.files, folderPath) : [];
        resolve(videos);
      });
    });

    if (currentVideos.length > 1) {
      GDI.playlist.videos = currentVideos;
      GDI.playlist.currentIndex = currentVideos.findIndex(v => v.streamUrl === streamUrl);
      if (GDI.playlist.currentIndex === -1) {
        GDI.playlist.videos.unshift({ name: filename, streamUrl: streamUrl, pageUrl: window.location.href, size: size, poster: poster, mimeType: mimeType });
        GDI.playlist.currentIndex = 0;
      }
      renderPlaylistUI();
      GDI.playlist.isBuilding = false;
      return;
    }

    // Caso contrário, tenta pasta pai
    const parentFolders = await new Promise(resolve => {
      requestListPath(parentPath, {}, (data) => {
        const folders = data?.data?.files?.filter(f => f.mimeType === "application/vnd.google-apps.folder") || [];
        resolve(folders);
      });
    });

    if (!parentFolders.length) {
      GDI.playlist.videos = [{ name: filename, streamUrl: streamUrl, pageUrl: window.location.href, size: size, poster: poster, mimeType: mimeType }];
      GDI.playlist.currentIndex = 0;
      GDI.playlist.isBuilding = false;
      return;
    }

    // Carrega vídeos de cada subpasta
    const allVideos = [];
    let completed = 0;

    parentFolders.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));

    parentFolders.forEach(folder => {
      const folderPath = parentPath + escapeHtmlId(folder.name) + "/";
      requestListPath(folderPath, {}, (data) => {
        if (data?.data?.files) {
          const videos = buildVideosFromFiles(data.data.files, folderPath, folder.name);
          videos.forEach(v => allVideos.push(v));
        }
        completed++;
        if (completed === parentFolders.length) {
          // Remove duplicatas e monta playlist final
          GDI.playlist.videos = allVideos.slice(0, 100);  // Limita a 100 vídeos
          GDI.playlist.currentIndex = GDI.playlist.videos.findIndex(v => v.streamUrl === streamUrl);
          if (GDI.playlist.currentIndex === -1) {
            GDI.playlist.videos.unshift({ name: filename, streamUrl: streamUrl, pageUrl: window.location.href, size: size, poster: poster, mimeType: mimeType });
            GDI.playlist.currentIndex = 0;
          }
          renderPlaylistUI();
          GDI.playlist.isBuilding = false;
        }
      });
    });
  }

  function renderPlaylistUI() {
    if (!GDI.playlist.videos.length) return;

    let html = "";
    GDI.playlist.videos.forEach((video, idx) => {
      const isCurrent = idx === GDI.playlist.currentIndex;
      const style = isCurrent 
        ? "background:var(--bs-primary);color:#fff;"
        : "background:rgba(255,255,255,0.05);color:var(--gdi-text);";
      
      html += `<div class="gdi-playlist-item" data-idx="${idx}" style="padding:8px 12px;margin:3px 0;border-radius:6px;cursor:pointer;font-size:13px;${style}">
        <i class="bi bi-${isCurrent ? 'play-fill' : 'film'} me-2"></i>
        ${escHtml(video.name)}
        <span style="float:right;font-size:11px;opacity:0.7;">${video.size || ""}</span>
      </div>`;
    });

    $("#gdi-playlist-list").html(html);
    $("#gdi-playlist-count").text(`${GDI.playlist.currentIndex + 1} / ${GDI.playlist.videos.length}`);
    $("#gdi-playlist-wrap").show();

    // Atualizar nav bar
    const navBar = document.getElementById("gdi-player-nav");
    if (navBar && GDI.playlist.videos.length > 1) {
      navBar.style.display = "flex";
      document.getElementById("gdi-nav-info").textContent = `${GDI.playlist.currentIndex + 1} / ${GDI.playlist.videos.length}`;
      document.getElementById("gdi-btn-prev").disabled = GDI.playlist.currentIndex <= 0;
      document.getElementById("gdi-btn-next").disabled = GDI.playlist.currentIndex >= GDI.playlist.videos.length - 1;
    }

    // Listeners de clique
    $(".gdi-playlist-item").off("click").on("click", function() {
      const idx = parseInt($(this).data("idx"));
      if (!isNaN(idx) && GDI.playlist.videos[idx]) switchVideo(idx);
    });
  }

  // ────── SWITCH VIDEO - VERSÃO CORRIGIDA ──────
  function switchVideo(newIndex) {
    if (newIndex < 0 || newIndex >= GDI.playlist.videos.length) return;
    GDI.playlist.currentIndex = newIndex;
    const video = GDI.playlist.videos[newIndex];

    if (video.pageUrl) history.pushState(null, video.name, video.pageUrl);

    // ✓ CORREÇÃO: Usa video.streamUrl ao invés de 'a'
    $(".gdi-file-header-name").text(video.name);
    $(".gdi-file-header-meta").text(video.size);
    
    const driveName = (window.drive_names && window.drive_names[window.current_drive_order || 0]) || "Drive";
    document.title = `${driveName} - ${video.name}`;

    if (!UI.disable_video_download) {
      $(".gdi-viewer-footer").html(renderDownloadButtons(video.streamUrl, escapeHtmlId(video.name), { showMedia: true }));
    }

    // Atualizar player com novo vídeo
    if (player_config.player === "plyr" && window._gdiPlayerInstance) {
      window._gdiPlayerInstance.source = {
        type: "video",
        title: video.name,
        sources: [{ src: video.streamUrl, type: isHLS ? "application/x-mpegURL" : "video/mp4" }]
      };
      window._gdiPlayerInstance.play().catch(() => {});
    } else if (player_config.player === "videojs" && window._gdiPlayerInstance) {
      window._gdiPlayerInstance.src({ src: video.streamUrl, type: isHLS ? "application/x-mpegURL" : "video/mp4" });
      window._gdiPlayerInstance.play().catch(() => {});
    }

    renderPlaylistUI();
  }

  // Iniciar construção de playlist
  buildPlaylist();

  // Carregar player script
  if (playerScript) {
    if (window.Plyr || window.videojs || window.DPlayer || window.jwplayer) {
      // Player já carregado
      initPlayer();
    } else {
      const script = document.createElement("script");
      script.src = playerScript;
      script.onload = initPlayer;
      document.head.appendChild(script);
    }
  }

  // ────── INIT PLAYER ──────
  function initPlayer() {
    if (player_config.player === "plyr") {
      window._gdiPlayerInstance = new Plyr("#player", { autoplay: true });
      window._gdiPlayerInstance.on("ended", () => {
        if (GDI.playlist.currentIndex < GDI.playlist.videos.length - 1) {
          switchVideo(GDI.playlist.currentIndex + 1);
        }
      });
    } else if (player_config.player === "videojs") {
      window._gdiPlayerInstance = videojs("vplayer", { autoplay: true });
      window._gdiPlayerInstance.on("ended", () => {
        if (GDI.playlist.currentIndex < GDI.playlist.videos.length - 1) {
          switchVideo(GDI.playlist.currentIndex + 1);
        }
      });
    }
    // ... outros players ...
  }

  // Botões de navegação
  document.getElementById("gdi-btn-prev")?.addEventListener("click", () => {
    if (GDI.playlist.currentIndex > 0) switchVideo(GDI.playlist.currentIndex - 1);
  });
  document.getElementById("gdi-btn-next")?.addEventListener("click", () => {
    if (GDI.playlist.currentIndex < GDI.playlist.videos.length - 1) {
      switchVideo(GDI.playlist.currentIndex + 1);
    }
  });
}

// ════════════════════════════════════════════════════════════════════
// HELPERS
// ════════════════════════════════════════════════════════════════════

function _viewerBreadcrumb() {
  return generateBreadcrumb(window.location.pathname);
}

function generateBreadcrumb(path) {
  const parts = path.split("/");
  let html = "";
  let breadcrumbPath = "";

  for (let i = 0; i < parts.length; i++) {
    let part = parts[i];
    breadcrumbPath += (i === 0 ? "" : "/") + part;
    const isLast = i === parts.length - 1;
    let displayName;

    try {
      displayName = decodeURIComponent(part);
    } catch {
      displayName = part;
    }

    const driveMatch = displayName.match(/^(\d+):$/);
    const name = driveMatch ? (window.drive_names && window.drive_names[+driveMatch[1]]) || displayName : displayName || "Home";
    const shortName = name.length > 20 ? name.slice(0, 16) + "…" : name;

    if (isLast) {
      html += `<li class="gdi-bc-cur" title="${escHtml(name)}">${escHtml(shortName)}</li>`;
    } else {
      html += `<li><a href="${breadcrumbPath ? breadcrumbPath + "/" : "/"}" title="${escHtml(name)}">${escHtml(shortName)}</a></li><li class="gdi-bc-sep">/</li>`;
    }
  }
  return html;
}

function _viewerCard(icon, filename, size, content, footer = "") {
  return `<div class="gdi-wrap">
    <div class="gdi-viewer">
      <div class="gdi-breadcrumb-wrap">
        <ol class="gdi-bc">${_viewerBreadcrumb()}</ol>
      </div>
      <div class="gdi-viewer-card">
        <div class="gdi-file-header">
          <span class="gdi-file-header-icon">${icon}</span>
          <div class="gdi-file-header-info">
            <div class="gdi-file-header-name">${escHtml(filename)}</div>
            <div class="gdi-file-header-meta">${escHtml(size)}</div>
          </div>
        </div>
        <div class="gdi-viewer-body">${content}</div>
        ${footer ? `<div class="gdi-viewer-footer">${footer}</div>` : ""}
      </div>
    </div>
  </div>`;
}

function renderDownloadButtons(url, filename_encoded, options = {}) {
  const showMedia = options.showMedia || false;
  const mediaLinks = showMedia ? `
    <li><a class="dropdown-item" href="iina://weblink?url=${url}"><i class="bi bi-play-circle me-2"></i>IINA</a></li>
    <li><a class="dropdown-item" href="vlc://${url}"><i class="bi bi-play-circle me-2"></i>VLC</a></li>
  ` : "";

  return `<div class="gdi-dl-wrap">
    <div class="gdi-dl-url-row">
      <span class="gdi-dl-url-text" id="dlurl" title="${escHtml(url)}">${escHtml(url)}</span>
      <button class="gdi-btn gdi-btn-ghost gdi-btn-icon" type="button" onclick="copyShareUrl(${escHtml(JSON.stringify(url))})" title="Copiar URL">
        <i class="bi bi-clipboard"></i>
      </button>
    </div>
    <div class="gdi-dl-actions">
      <a href="${url}" class="gdi-btn gdi-btn-primary"><i class="bi bi-download"></i> Download</a>
      <div class="dropdown">
        <button type="button" class="gdi-btn gdi-btn-ghost gdi-btn-icon dropdown-toggle" data-bs-toggle="dropdown">
          <i class="bi bi-three-dots-vertical"></i>
        </button>
        <ul class="dropdown-menu">
          ${mediaLinks}
          <li><a class="dropdown-item" href="#">Mais opções</a></li>
        </ul>
      </div>
    </div>
  </div>`;
}

function copyShareUrl(url) {
  navigator.clipboard.writeText(url)
    .then(() => showToast("Link copiado!"))
    .catch(() => {
      const textarea = document.createElement("textarea");
      textarea.value = url;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
      showToast("Link copiado!");
    });
}

function showToast(message) {
  let container = document.getElementById("gdi-toast-container");
  if (!container) {
    container = document.createElement("div");
    container.id = "gdi-toast-container";
    document.body.appendChild(container);
  }
  const toast = document.createElement("div");
  toast.className = "gdi-toast";
  toast.innerHTML = `<i class="bi bi-check-circle-fill"></i> ${message}`;
  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.add("gdi-toast-out");
    setTimeout(() => toast.remove(), 200);
  }, 2400);
}

// ════════════════════════════════════════════════════════════════════
// CLEANUP EM NAVEGAÇÃO SPA
// ════════════════════════════════════════════════════════════════════

function cleanupGDI() {
  // Cancelar todas as requisições pendentes
  GDI.abortControllers.forEach(controller => {
    try { controller.abort(); } catch (e) {}
  });
  GDI.abortControllers.clear();

  // Reset estado
  GDI.playlist = { videos: [], currentIndex: -1, isBuilding: false };

  console.log("[GDI] Cleanup concluído");
}

// Hook em navegação SPA
window.addEventListener("beforeunload", cleanupGDI);
window.onpopstate = function() {
  cleanupGDI();
  // ... render nova página ...
};

console.log("✅ GDI App v2.0 Carregado - Versão Corrigida");
